const items = $input.all();

// Limit to first 10 items for testing
const limitedItems = items.slice(0, 10);

// Map PropWire columns to your scoring system format
const mappedProperties = limitedItems.map(property => ({
  // Property Info
  address: property['T Address'] || '',
  city: property['T City'] || '',
  state: property['T State'] || '',
  zip: property['T Zip'] || '',
  property_value: parseInt(property['T Estimated Value']) || 0,
  lot_size_acres: parseFloat(property['T Lot (Acres)']) || 0,
  square_feet: parseInt(property['T Living Square Feet']) || 0,
  bedrooms: parseInt(property['T Bedrooms']) || 0,
  bathrooms: parseInt(property['T Bathrooms']) || 0,
  year_built: parseInt(property['T Year Built']) || 1990,
  property_type: property['T Property Type'] || 'Single Family',

  // Owner Info
  owner_first_name: property['T Owner 1 First Name'] || '',
  owner_last_name: property['T Owner 1 Last Name'] || '',
  absentee_owner: property['T Owner Occupied'] === '0' || property['T Vacant?'] === '1',
  equity_percentage: parseFloat(property['T Estimated Equity Percent']) || 0,

  // Financial Data
  last_sale_date: property['T Last Sale Date'] || '',
  last_sale_price: parseInt(property['T Last Sale Amount']) || 0,

  // Additional
  apn: property['T APN'] || ''
}));

return mappedProperties;

// Get all items from Extract from File node
const items = $input.all();

// Limit to first 10 items for testing
const limitedItems = items.slice(0, 10);

// Map PropWire columns to your scoring system format
const mappedProperties = limitedItems.map(item => {
  // Access the actual data from the n8n item structure
  const property = item.json;

  // Helper function to safely parse numbers
  const safeParse = (value, defaultVal = 0) => {
    if (value === undefined || value === null || value === '') return defaultVal;
    const parsed = parseFloat(value.toString().trim());
    return isNaN(parsed) ? defaultVal : parsed;
  };

  return {
    // Property Info
    address: property['T Address'] || '',
    city: property['T City'] || '',
    state: property['T State'] || '',
    zip: property['T Zip'] || '',
    property_value: safeParse(property['T Estimated Value']),
    lot_size_acres: safeParse(property['T Lot (Acres)']),
    square_feet: safeParse(property['T Living Square Feet']),
    bedrooms: safeParse(property['T Bedrooms']),
    bathrooms: safeParse(property['T Bathrooms']),
    year_built: safeParse(property['T Year Built'], 1990),
    property_type: property['T Property Type'] || 'Single Family',

    // Owner Info
    owner_first_name: property['T Owner 1 First Name'] || '',
    owner_last_name: property['T Owner 1 Last Name'] || '',
    absentee_owner: property['T Owner Occupied'] === '0' || property['T Vacant?'] === '1',
    equity_percentage: safeParse(property['T Estimated Equity Percent']),

    // Financial Data
    last_sale_date: property['T Last Sale Date'] || '',
    last_sale_price: safeParse(property['T Last Sale Amount']),

    // Additional
    apn: property['T APN'] || ''
  };
});

return mappedProperties;

