        marketReasons.push(`Rural area (${populationDensity} people/sq mi): +90 points - LOW COMPETITION`);
      } else if (populationDensity <= 5000) {
        saturationScore = 70; // Suburban = moderate competition
        marketReasons.push(`Suburban area (${populationDensity} people/sq mi): +70 points - MODERATE COMPETITION`);
      } else {
        saturationScore = 50; // Urban = high competition
        marketReasons.push(`Urban area (${populationDensity} people/sq mi): +50 points - HIGH COMPETITION`);
      }
    } else {
      saturationScore = 60; // Default moderate competition
      marketReasons.push(`Unknown competition level: +60 points (default)`);
    }
  }

  // 2. MARKET GROWTH (Economic Health) (0-80 points)
  let growthScore = 0;

  // Property value growth trend
  if ($json.market_growth_rate !== undefined && $json.market_growth_rate !== null) {
    const growthRate = parseFloat($json.market_growth_rate);

    if (growthRate >= 15) {
      growthScore = 80; // Rapidly growing market
      marketReasons.push(`Rapid market growth (${growthRate}%): +80 points - BOOMING MARKET`);
    } else if (growthRate >= 10) {
      growthScore = 70; // Strong growth
      marketReasons.push(`Strong market growth (${growthRate}%): +70 points - STRONG MARKET`);
    } else if (growthRate >= 5) {
      growthScore = 60; // Moderate growth
      marketReasons.push(`Moderate market growth (${growthRate}%): +60 points - HEALTHY MARKET`);
    } else if (growthRate >= 0) {
      growthScore = 40; // Stable market
      marketReasons.push(`Stable market (${growthRate}%): +40 points - STABLE MARKET`);
    } else {
      growthScore = 20; // Declining market
      marketReasons.push(`Declining market (${growthRate}%): +20 points - WEAK MARKET`);
    }
  } else {
    // Estimate based on neighborhood value trend
    if ($json.neighborhood_value_trend !== undefined && $json.neighborhood_value_trend !== null) {
      const valueTrend = $json.neighborhood_value_trend.toLowerCase();
      if (valueTrend === 'increasing_fast' || valueTrend === 'increasing_10plus') {
        growthScore = 70; // Rapidly increasing values
        marketReasons.push(`Rapidly increasing neighborhood values: +70 points - STRONG MARKET`);
      } else if (valueTrend === 'increasing') {
        growthScore = 60; // Increasing values
        marketReasons.push(`Increasing neighborhood values: +60 points - HEALTHY MARKET`);
      } else if (valueTrend === 'stable') {
        growthScore = 40; // Stable values
        marketReasons.push(`Stable neighborhood values: +40 points - STABLE MARKET`);
      } else {
        growthScore = 20; // Declining values
        marketReasons.push(`Declining neighborhood values: +20 points - WEAK MARKET`);
      }
    } else {
      growthScore = 50; // Default moderate growth
      marketReasons.push(`Unknown market growth: +50 points (default)`);
    }
  }

  // 3. ECONOMIC INDICATORS (Spending Power) (0-60 points)
  let economicScore = 0;

  // Unemployment rate
  if ($json.unemployment_rate !== undefined && $json.unemployment_rate !== null) {
    const unemploymentRate = parseFloat($json.unemployment_rate);

    if (unemploymentRate <= 3) {
      economicScore += 30; // Very low unemployment = high spending power
      marketReasons.push(`Very low unemployment (${unemploymentRate}%): +30 points - HIGH SPENDING POWER`);
    } else if (unemploymentRate <= 5) {
      economicScore += 25; // Low unemployment
      marketReasons.push(`Low unemployment (${unemploymentRate}%): +25 points - GOOD SPENDING POWER`);
    } else if (unemploymentRate <= 7) {
      economicScore += 15; // Moderate unemployment
      marketReasons.push(`Moderate unemployment (${unemploymentRate}%): +15 points - MODERATE SPENDING POWER`);
    } else if (unemploymentRate <= 10) {
      economicScore += 5; // High unemployment
      marketReasons.push(`High unemployment (${unemploymentRate}%): +5 points - LIMITED SPENDING POWER`);
    } else {
      economicScore += 0; // Very high unemployment
      marketReasons.push(`Very high unemployment (${unemploymentRate}%): +0 points - LOW SPENDING POWER`);
    }
  } else {
    economicScore += 15; // Default moderate unemployment
    marketReasons.push(`Unknown unemployment rate: +15 points (default)`);
  }

  // Median household income trend
  if ($json.income_trend !== undefined && $json.income_trend !== null) {
    const incomeTrend = $json.income_trend.toLowerCase();
    if (incomeTrend === 'increasing_fast' || incomeTrend === 'increasing_10plus') {
      economicScore += 30; // Rapidly increasing income
      marketReasons.push(`Rapidly increasing income: +30 points - STRONG ECONOMIC GROWTH`);
    } else if (incomeTrend === 'increasing') {
      economicScore += 20; // Increasing income
      marketReasons.push(`Increasing income: +20 points - GOOD ECONOMIC GROWTH`);
    } else if (incomeTrend === 'stable') {
      economicScore += 10; // Stable income
      marketReasons.push(`Stable income: +10 points - STABLE ECONOMIC CONDITIONS`);
    } else {
      economicScore += 0; // Declining income
      marketReasons.push(`Declining income: +0 points - WEAK ECONOMIC CONDITIONS`);
    }
  } else {
    economicScore += 15; // Default moderate income trend
    marketReasons.push(`Unknown income trend: +15 points (default)`);
  }

  // Cap economic score at 60 points
  economicScore = Math.min(economicScore, 60);

  // 4. SEASONAL MARKET CONDITIONS (0-40 points)
  let seasonalScore = 0;
  const currentMonth = new Date().getMonth() + 1;

  // Spring and fall are peak seasons for home improvement
  if ([3, 4, 5].includes(currentMonth)) {
    seasonalScore = 40; // Spring - peak season
    marketReasons.push(`Spring season (March-May): +40 points - PEAK HOME IMPROVEMENT SEASON`);
  } else if ([9, 10].includes(currentMonth)) {
    seasonalScore = 35; // Fall - high season
    marketReasons.push(`Fall season (September-October): +35 points - HIGH HOME IMPROVEMENT SEASON`);
  } else if ([6, 7, 8].includes(currentMonth)) {
    seasonalScore = 25; // Summer - moderate season
    marketReasons.push(`Summer season (June-August): +25 points - MODERATE HOME IMPROVEMENT SEASON`);
  } else {
    seasonalScore = 15; // Winter - low season
    marketReasons.push(`Winter season (November-February): +15 points - LOW HOME IMPROVEMENT SEASON`);
  }

  // 5. MARKET MATURITY (0-30 points)
  let maturityScore = 0;

  // Market maturity based on property age distribution
  if ($json.market_maturity !== undefined && $json.market_maturity !== null) {
    const maturity = $json.market_maturity.toLowerCase();
    if (maturity === 'emerging') {
      maturityScore = 30; // Emerging market = high opportunity
      marketReasons.push(`Emerging market: +30 points - HIGH OPPORTUNITY`);
    } else if (maturity === 'growing') {
      maturityScore = 25; // Growing market
      marketReasons.push(`Growing market: +25 points - GOOD OPPORTUNITY`);
    } else if (maturity === 'mature') {
      maturityScore = 15; // Mature market
      marketReasons.push(`Mature market: +15 points - MODERATE OPPORTUNITY`);
    } else if (maturity === 'declining') {
      maturityScore = 5; // Declining market
      marketReasons.push(`Declining market: +5 points - LOW OPPORTUNITY`);
    } else {
      maturityScore = 20; // Unknown maturity
      marketReasons.push(`Unknown market maturity: +20 points (default)`);
    }
  } else {
    // Estimate based on property age
    if ($json.year_built !== undefined && $json.year_built !== null) {
      const yearBuilt = parseInt($json.year_built);
      const currentYear = new Date().getFullYear();
      const propertyAge = currentYear - yearBuilt;

      if (propertyAge <= 10) {
        maturityScore = 25; // New development = emerging market
        marketReasons.push(`New development (${propertyAge} years old): +25 points - EMERGING MARKET`);
      } else if (propertyAge <= 25) {
        maturityScore = 20; // Established development = growing market
        marketReasons.push(`Established development (${propertyAge} years old): +20 points - GROWING MARKET`);
      } else {
        maturityScore = 15; // Older development = mature market
        marketReasons.push(`Older development (${propertyAge} years old): +15 points - MATURE MARKET`);
      }
    } else {
      maturityScore = 20; // Default moderate maturity
      marketReasons.push(`Unknown market maturity: +20 points (default)`);
    }
  }

  // 6. CALCULATE FINAL MARKET SCORE
  const rawScore = saturationScore + growthScore + economicScore + seasonalScore + maturityScore;

  // Normalize to 0-100 scale (310 max becomes 100)
  marketScore = Math.round((rawScore / 310) * 100);

  // Ensure bounds
  marketScore = Math.min(marketScore, 100);
  marketScore = Math.max(marketScore, 0);

  // Add summary to reasons
  marketReasons.push(`Raw Score: ${rawScore}/310 → Normalized: ${marketScore}/100`);

  // Return the result
  return [{
    json: {
      ...$json, // Preserve all original data (including enhanced urgency_score, property_score, financial_score, and demographic_score)
      market_score: marketScore,
      market_reasons: marketReasons,
      market_breakdown: {
        saturation_score: saturationScore,
        growth_score: growthScore,
        economic_score: economicScore,
        seasonal_score: seasonalScore,
        maturity_score: maturityScore,
        raw_score: rawScore,
        normalized_score: marketScore
      }
    }
  }];

} catch (error) {
  // Error handling - return safe defaults
  console.error('Error in Enhanced Market Module:', error);

  return [{
    json: {
      ...$json, // Preserve original data
      market_score: 40, // Safe default score
      market_reasons: [
        "Error in market calculation: +40 points (default)",
        "Check data quality and try again"
      ],
      market_breakdown: {
        saturation_score: 60,
        growth_score: 50,
        economic_score: 30,
        seasonal_score: 25,
        maturity_score: 20,
        raw_score: 185,
        normalized_score: 40
      },
      error: error.message
    }
  }];
}

// UNIVERSAL FINAL SCORING MODULE - HOT LEAD FINDER
// Combines all 5 enhanced modules with universal weights (no service classification)
// Output: Universal spending likelihood score + tier assignment + comprehensive breakdown

try {
  // Initialize variables
  let finalScore = 0;
  let tier = '';
  let tierDescription = '';
  let finalReasons = [];

  // Get individual module scores
  const urgencyScore = $json.urgency_score || 0;
  const propertyScore = $json.property_score || 0;
  const financialScore = $json.financial_score || 0;
  const demographicScore = $json.demographic_score || 0;
  const marketScore = $json.market_score || 0;

  // UNIVERSAL WEIGHTS (Optimized for general spending likelihood)
  const weights = {
    urgency: 0.25,      // 25% - Timing is crucial for new homeowners
    property: 0.20,     // 20% - Property characteristics drive renovation needs
    financial: 0.25,    // 25% - Financial capacity determines spending ability
    demographic: 0.20,  // 20% - Demographics predict spending behavior
    market: 0.10        // 10% - Market conditions affect opportunity
  };

  // Calculate weighted final score
  const weightedScore = (
    (urgencyScore * weights.urgency) +
    (propertyScore * weights.property) +
    (financialScore * weights.financial) +
    (demographicScore * weights.demographic) +
    (marketScore * weights.market)
  );

  // Round to whole number
  finalScore = Math.round(weightedScore);

  // Ensure bounds
  finalScore = Math.min(finalScore, 100);
  finalScore = Math.max(finalScore, 0);

  // TIER ASSIGNMENT (Universal spending likelihood tiers)
  if (finalScore >= 85) {
    tier = 'HOT';
    tierDescription = 'ULTRA-HIGH SPENDING LIKELIHOOD - IMMEDIATE PRIORITY';
  } else if (finalScore >= 75) {
    tier = 'WARM';
    tierDescription = 'HIGH SPENDING LIKELIHOOD - HIGH PRIORITY';
  } else if (finalScore >= 60) {
    tier = 'COOL';
    tierDescription = 'MODERATE SPENDING LIKELIHOOD - MEDIUM PRIORITY';
  } else if (finalScore >= 40) {
    tier = 'COLD';
    tierDescription = 'LOW SPENDING LIKELIHOOD - LOW PRIORITY';
  } else {
    tier = 'FROZEN';
    tierDescription = 'MINIMAL SPENDING LIKELIHOOD - MINIMAL PRIORITY';
  }

  // Build comprehensive reasons array
  finalReasons.push(`=== UNIVERSAL FINAL SCORE: ${finalScore}/100 ===`);
  finalReasons.push(`=== TIER: ${tier} - ${tierDescription} ===`);
  finalReasons.push('');

  // Module breakdown with weights
  finalReasons.push('MODULE BREAKDOWN:');
  finalReasons.push(`• Urgency/Timing: ${urgencyScore}/100 (${(weights.urgency * 100)}% weight) = ${Math.round(urgencyScore * weights.urgency)} points`);
  finalReasons.push(`• Property Characteristics: ${propertyScore}/100 (${(weights.property * 100)}% weight) = ${Math.round(propertyScore * weights.property)} points`);
  finalReasons.push(`• Financial Capacity: ${financialScore}/100 (${(weights.financial * 100)}% weight) = ${Math.round(financialScore * weights.financial)} points`);
  finalReasons.push(`• Demographic Fit: ${demographicScore}/100 (${(weights.demographic * 100)}% weight) = ${Math.round(demographicScore * weights.demographic)} points`);
  finalReasons.push(`• Market Conditions: ${marketScore}/100 (${(weights.market * 100)}% weight) = ${Math.round(marketScore * weights.market)} points`);
  finalReasons.push('');

  // Top contributing factors
  const moduleScores = [
    { name: 'Urgency/Timing', score: urgencyScore, weight: weights.urgency },
    { name: 'Property Characteristics', score: propertyScore, weight: weights.property },
    { name: 'Financial Capacity', score: financialScore, weight: weights.financial },
    { name: 'Demographic Fit', score: demographicScore, weight: weights.demographic },
    { name: 'Market Conditions', score: marketScore, weight: weights.market }
  ];

  // Sort by weighted contribution
  moduleScores.sort((a, b) => (b.score * b.weight) - (a.score * a.weight));

  finalReasons.push('TOP CONTRIBUTING FACTORS:');
  moduleScores.forEach((module, index) => {
    const contribution = Math.round(module.score * module.weight);
    finalReasons.push(`${index + 1}. ${module.name}: ${contribution} points (${module.score}/100 score)`);
  });
  finalReasons.push('');

  // Spending likelihood analysis
  finalReasons.push('SPENDING LIKELIHOOD ANALYSIS:');
  if (finalScore >= 85) {
    finalReasons.push('🔥 ULTRA-HIGH: This lead is extremely likely to spend $10k-50k+ on home improvements');
    finalReasons.push('   • Contact within 24 hours');
    finalReasons.push('   • Offer premium services');
    finalReasons.push('   • Expect high-value projects');
  } else if (finalScore >= 75) {
    finalReasons.push('🔥 HIGH: This lead is very likely to spend $5k-25k on home improvements');
    finalReasons.push('   • Contact within 48 hours');
    finalReasons.push('   • Offer comprehensive services');
    finalReasons.push('   • Expect medium to high-value projects');
  } else if (finalScore >= 60) {
    finalReasons.push('🔥 MODERATE: This lead may spend $2k-15k on home improvements');
    finalReasons.push('   • Contact within 1 week');
    finalReasons.push('   • Offer standard services');
    finalReasons.push('   • Expect medium-value projects');
  } else if (finalScore >= 40) {
    finalReasons.push('🔥 LOW: This lead may spend $500-5k on home improvements');
    finalReasons.push('   • Contact within 2 weeks');
    finalReasons.push('   • Offer basic services');
    finalReasons.push('   • Expect low to medium-value projects');
  } else {
    finalReasons.push('🔥 MINIMAL: This lead is unlikely to spend significant amounts');
    finalReasons.push('   • Contact when time permits');
    finalReasons.push('   • Offer basic services only');
    finalReasons.push('   • Expect low-value projects');
  }

  // Learning data structure for System 3 optimization
  const learningData = {
    timestamp: new Date().toISOString(),
    property_id: $json.property_id || 'unknown',
    address: $json.address || 'unknown',
    final_score: finalScore,
    tier: tier,
    module_scores: {
      urgency: urgencyScore,
      property: propertyScore,
      financial: financialScore,
      demographic: demographicScore,
      market: marketScore
    },
    module_weights: weights,
    weighted_contributions: {
      urgency: Math.round(urgencyScore * weights.urgency),
      property: Math.round(propertyScore * weights.property),
      financial: Math.round(financialScore * weights.financial),
      demographic: Math.round(demographicScore * weights.demographic),
      market: Math.round(marketScore * weights.market)
    },
    data_quality: {
      urgency_data_complete: ($json.urgency_reasons && $json.urgency_reasons.length > 0),
      property_data_complete: ($json.property_reasons && $json.property_reasons.length > 0),
      financial_data_complete: ($json.financial_reasons && $json.financial_reasons.length > 0),
      demographic_data_complete: ($json.demographic_reasons && $json.demographic_reasons.length > 0),
      market_data_complete: ($json.market_reasons && $json.market_reasons.length > 0)
    }
  };

  // Return comprehensive result
  return [{
    json: {
      ...$json, // Preserve all original data and module scores

      // Final scoring results
      final_score: finalScore,
      tier: tier,
      tier_description: tierDescription,
      final_reasons: finalReasons,

      // Comprehensive breakdown
      final_breakdown: {
        urgency_contribution: Math.round(urgencyScore * weights.urgency),
        property_contribution: Math.round(propertyScore * weights.property),
        financial_contribution: Math.round(financialScore * weights.financial),
        demographic_contribution: Math.round(demographicScore * weights.demographic),
        market_contribution: Math.round(marketScore * weights.market),
        total_weighted_score: finalScore,
        weights_used: weights
      },

      // Learning data for System 3
      learning_data: learningData,

      // Customer tracking fields
      customer_wants: [], // To be filled by sales team
      actual_spending: null, // To be filled after conversion
      conversion_date: null, // To be filled after conversion
      project_value: null, // To be filled after conversion
      services_purchased: [], // To be filled after conversion

      // System 3 optimization fields
      prediction_accuracy: null, // To be calculated by System 3
      weight_optimization: null, // To be calculated by System 3
      model_improvement: null // To be calculated by System 3
    }
  }];

} catch (error) {
  // Error handling - return safe defaults
  console.error('Error in Universal Final Scoring:', error);

  return [{
    json: {
      ...$json, // Preserve original data
      final_score: 30, // Safe default score
      tier: 'COLD',
      tier_description: 'ERROR IN CALCULATION - LOW PRIORITY',
      final_reasons: [
        "Error in final scoring calculation: +30 points (default)",
        "Check data quality and try again",
        error.message
      ],
      final_breakdown: {
        urgency_contribution: 0,
        property_contribution: 0,
        financial_contribution: 0,
        demographic_contribution: 0,
        market_contribution: 0,
        total_weighted_score: 30,
        weights_used: { urgency: 0.25, property: 0.20, financial: 0.25, demographic: 0.20, market: 0.10 }
      },
      learning_data: {
        timestamp: new Date().toISOString(),
        error: error.message,
        final_score: 30,
        tier: 'COLD'
      },
      error: error.message
    }
  }];
}

